-- A subsidy is an internal assignment of verified corporate bank funds, never a fabricated bank transaction.
create or replace function reloo_promotion_credit_total(p_profile text) returns numeric language sql stable security definer set search_path=public as $$select coalesce(sum(amount),0) from promotion_subsidy_credits where profile_id=p_profile$$;
do $$begin if to_regprocedure('public.reloo_wallet_snapshot_before_promotion(text)') is null then alter function reloo_wallet_snapshot(text) rename to reloo_wallet_snapshot_before_promotion;end if;end $$;
create or replace function reloo_wallet_snapshot(p_profile text) returns jsonb language sql security definer set search_path=public as $$
select reloo_wallet_snapshot_before_promotion(p_profile)||jsonb_build_object('subsidiesCount',(select count(*) from promotion_subsidy_credits where profile_id=p_profile),'subsidies',coalesce((select jsonb_agg(row) from (select jsonb_build_object('id',c.id,'redemptionId',r.id,'profileId',c.profile_id,'amount',c.amount::text,'occurredAt',c.created_at,'quote',r.quote,'receipt',r.receipt,'evidence',jsonb_set(to_jsonb(s),'{amount}',to_jsonb(s.amount::text))) row from promotion_subsidy_credits c join promotion_redemptions r on r.id=c.redemption_id join promotion_funding f on f.id=c.funding_id join finance_sources s on s.id=f.source_id where c.profile_id=p_profile order by c.created_at desc limit 10000) q),'[]'));
$$;
do $$begin if to_regprocedure('public.reloo_payout_available_before_promotion(text,uuid)') is null then alter function reloo_payout_available(text,uuid) rename to reloo_payout_available_before_promotion;end if;end $$;
create or replace function reloo_payout_available(p_profile text,p_exclude uuid default null) returns jsonb language sql security definer set search_path=public as $$
with groups as(select unnest(array['BANK','RENTAL','DEPOSIT','REFUND','SHOPEE','TIKTOK']) code), credits as(select source_code,sum(amount)::numeric n from cashflow_payout_credits where profile_id=p_profile group by source_code), used as(select source_code,sum(amount)::numeric n from wallet_withdrawal_records where profile_id=p_profile and id is distinct from p_exclude and status in ('REQUESTED','APPROVED','PROCESSING','PAID') group by source_code), bank as(select coalesce(sum(case when direction='IN' then amount else -amount end),0)::numeric+reloo_promotion_credit_total(p_profile) n from customer_cash_entries where profile_id=p_profile), deposit as(select coalesce(sum(case when e.direction='IN' then e.amount else 0 end),0)::numeric n from customer_cash_entries e where e.profile_id=p_profile and (select source_code from wallet_category_events c where c.entry_id=e.id order by event_sequence desc limit 1)='DEPOSIT'), pending as(select coalesce(sum(amount),0)::numeric n from wallet_withdrawal_records where profile_id=p_profile and id is distinct from p_exclude and status in ('REQUESTED','APPROVED','PROCESSING')), rewards as(select upper(a.merchant) code,coalesce(sum(l.amount),0)::numeric n from cashback_ledger l join cashback_conversions c on c.id=l.conversion_id join affiliate_clicks a on a.id=c.click_id where l.profile_id=p_profile and a.profile_id=p_profile group by upper(a.merchant)), released_deposit as(select coalesce(sum(amount),0)::numeric n from cashflow_payout_credits where profile_id=p_profile and source_code='DEPOSIT'), pool as(select greatest(bank.n-greatest(deposit.n-released_deposit.n,0)-pending.n,0) n from bank,deposit,pending,released_deposit), available as(select g.code,greatest(least(coalesce(c.n,0)-coalesce(u.n,0),pool.n,case when g.code in ('SHOPEE','TIKTOK') then coalesce(r.n,0)-coalesce(u.n,0) else 9007199254740991::numeric end),0) n from groups g cross join pool left join credits c on c.source_code=g.code left join used u on u.source_code=g.code left join rewards r on r.code=g.code)
select jsonb_build_object('sources',(select jsonb_object_agg(code,n::text) from available),'total',(select least(sum(available.n),pool.n)::text from available cross join pool group by pool.n),'bankPool',(select n::text from pool));
$$;
do $$begin if to_regprocedure('public.reloo_release_payout_before_promotion(text,text,text,bigint,uuid,text)') is null then alter function reloo_release_payout(text,text,text,bigint,uuid,text) rename to reloo_release_payout_before_promotion;end if;end $$;
create or replace function reloo_release_payout(p_actor text,p_profile text,p_source text,p_amount bigint,p_funding uuid,p_reason text) returns uuid language plpgsql security definer set search_path=public as $$
declare entitlement numeric;paid numeric;fund finance_sources;new_id uuid;
begin
 if not reloo_staff_permission(p_actor,'accounting.write') then raise exception 'PERMISSION_REQUIRED';end if;
 perform pg_advisory_xact_lock(hashtext('payout:'||p_profile));
 if exists(select 1 from customer_cash_entries where source_id=p_funding and profile_id=p_profile) then return reloo_release_payout_before_promotion(p_actor,p_profile,p_source,p_amount,p_funding,p_reason);end if;
 select * into fund from finance_sources where id=p_funding for update;if not found or fund.direction<>'IN' or p_source<>'RENTAL' or p_amount<=0 or length(trim(p_reason)) not between 20 and 2000 then raise exception 'VERIFIED_FUNDING_REQUIRED';end if;
 select coalesce(sum(c.amount),0) into entitlement from promotion_subsidy_credits c join promotion_funding f on f.id=c.funding_id where c.profile_id=p_profile and f.source_id=p_funding;
 select coalesce(sum(amount),0) into paid from cashflow_payout_credits where profile_id=p_profile and funding_source_id=p_funding;
 if paid+p_amount>entitlement then raise exception 'SUBSIDY_ENTITLEMENT_REQUIRED';end if;
 insert into cashflow_payout_credits(profile_id,source_code,amount,funding_source_id,reason,created_by) values(p_profile,p_source,p_amount,p_funding,p_reason,p_actor) returning id into new_id;
 insert into security_audit(actor_id,subject_id,action,details) values(p_actor,p_profile,'PAYOUT_SUBSIDY_RELEASED',jsonb_build_object('creditId',new_id,'amount',p_amount::text,'fundingSourceId',p_funding,'reason',p_reason));return new_id;
end $$;
-- Corporate promotion funds cannot later be re-labelled as a customer's incoming VA transfer.
create or replace function reloo_protect_promotion_funds() returns trigger language plpgsql set search_path=public as $$begin if exists(select 1 from promotion_funding where source_id=new.source_id) then raise exception 'CORPORATE_PROMOTION_FUNDS_LOCKED';end if;return new;end $$;
drop trigger if exists promotion_funds_guard on customer_cash_entries;
create trigger promotion_funds_guard before insert on customer_cash_entries for each row execute function reloo_protect_promotion_funds();
revoke all on function reloo_promotion_credit_total(text),reloo_wallet_snapshot(text),reloo_payout_available(text,uuid),reloo_release_payout(text,text,text,bigint,uuid,text) from public,anon,authenticated;
grant execute on function reloo_promotion_credit_total(text),reloo_wallet_snapshot(text),reloo_payout_available(text,uuid),reloo_release_payout(text,text,text,bigint,uuid,text) to service_role;
notify pgrst,'reload schema';
